class Solution {
    int rows[9], cols[9], boxes[9];

    int boxIndex(int r, int c) {
        return (r / 3) * 3 + (c / 3);
    }

    bool solve(vector<vector<char>>& board, int filled) {
        if (filled == 81) return true;

        int bestR = -1, bestC = -1, bestCount = 10, bestMask = 0;
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] != '.') continue;
                int b = boxIndex(r, c);
                int used = rows[r] | cols[c] | boxes[b];
                int avail = (~used) & 0x1FF;
                int cnt = __builtin_popcount(avail);
                if (cnt < bestCount) {
                    bestCount = cnt;
                    bestR = r;
                    bestC = c;
                    bestMask = avail;
                    if (cnt == 0) return false;
                    if (cnt == 1) break;
                }
            }
            if (bestCount == 1) break;
        }

        int r = bestR, c = bestC;
        int b = boxIndex(r, c);
        int avail = bestMask;
        while (avail) {
            int low = avail & (-avail);
            int d = __builtin_ctz(low);
            board[r][c] = '1' + d;
            rows[r] |= (1 << d);
            cols[c] |= (1 << d);
            boxes[b] |= (1 << d);
            if (solve(board, filled + 1)) return true;
            rows[r] &= ~(1 << d);
            cols[c] &= ~(1 << d);
            boxes[b] &= ~(1 << d);
            board[r][c] = '.';
            avail &= avail - 1;
        }
        return false;
    }

public:
    void solveSudoku(vector<vector<char>>& board) {
        for (int i = 0; i < 9; i++) {
            rows[i] = cols[i] = boxes[i] = 0;
        }
        int filled = 0;
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] != '.') {
                    int d = board[r][c] - '1';
                    rows[r] |= (1 << d);
                    cols[c] |= (1 << d);
                    boxes[boxIndex(r, c)] |= (1 << d);
                    filled++;
                }
            }
        }
        solve(board, filled);
    }
};
